pub const AUTOGEN_VERSION: u32 = 1;

/// Aggregated loading progress across all enabled Quillshade domains.
///
/// Emitted once per change while [`QuillshadeLoader::load`] (or automatic first-frame loading) is in flight;
/// loading finishes when `loaded + failed == total` ([`QuillshadeReady`]).
#[derive(Message, Debug, Clone, Copy, PartialEq, Eq)]
pub struct QuillshadeProgress {
    /// Assets that have finished loading successfully across all enabled domains.
    pub loaded: u32,
    /// Assets that failed to load across all enabled domains.
    pub failed: u32,
    /// Total assets tracked across all enabled domains.
    pub total: u32,
}

/// Emitted once when all enabled Quillshade domains have finished loading their baked assets.
#[derive(Message, Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct QuillshadeReady;

#[derive(Resource, Default, Debug)]
struct QuillshadeLoaderState {
    ready: bool,
    sent_progress: Option<QuillshadeProgress>,
}

/// Unified [`SystemParam`] that starts or queries asset loading across all enabled Quillshade domains.
#[derive(SystemParam)]
pub struct QuillshadeLoader<'w> {
    state: ResMut<'w, QuillshadeLoaderState>,
    material: material::BakedMaterialsLoader<'w>,
    light: light::BakedLightLoader<'w>,
    data: data::BakedDataLoader<'w>,
}

impl QuillshadeLoader<'_> {
    /// Starts loading baked assets for all enabled domains if not already started.
    ///
    /// Returns the total number of tracked assets across all enabled domains.
    pub fn load(&mut self) -> u32 {
        self.material.load() + self.light.load() + self.data.load()
    }

    /// Loads the Material domain from `manifest` instead of [`material::COMPILED_MANIFEST`] (tests);
    /// ignored once loading has started.
    #[doc(hidden)]
    pub fn load_from_str(&mut self, manifest: &str) {
        self.material.load_from_str(manifest);
    }

    /// Current aggregated `(loaded, failed, total)` progress across all enabled domains.
    pub fn progress(&self) -> QuillshadeProgress {
        let mut loaded = 0u32;
        let mut failed = 0u32;
        let mut total = 0u32;
        let p = self.material.progress();
        loaded += p.loaded;
        failed += p.failed;
        total += p.total;
        let p = self.light.progress();
        loaded += p.loaded;
        failed += p.failed;
        total += p.total;
        let p = self.data.progress();
        loaded += p.loaded;
        failed += p.failed;
        total += p.total;
        QuillshadeProgress { loaded, failed, total }
    }

    /// `true` once every enabled domain has finished loading its baked assets.
    pub fn is_ready(&self) -> bool {
        self.state.ready || self.domains_ready()
    }

    fn domains_started(&self) -> bool {
        self.material.is_started() && self.light.is_started() && self.data.is_started()
    }

    fn domains_ready(&self) -> bool {
        self.material.is_ready() && self.light.is_ready() && self.data.is_ready()
    }
}

fn track_quillshade_progress(
    mut loader: QuillshadeLoader,
    mut progress_out: MessageWriter<QuillshadeProgress>,
    mut ready_out: MessageWriter<QuillshadeReady>,
) {
    if loader.state.ready || !loader.domains_started() {
        return;
    }
    let progress = loader.progress();
    if loader.state.sent_progress != Some(progress) {
        loader.state.sent_progress = Some(progress);
        progress_out.write(progress);
    }
    if loader.domains_ready() && progress.loaded + progress.failed >= progress.total {
        loader.state.ready = true;
        ready_out.write(QuillshadeReady);
    }
}

/// Registers [`QuillshadeProgress`], [`QuillshadeReady`], and [`QuillshadeLoader`] progress tracking.
#[derive(Default)]
pub struct QuillshadeLoaderPlugin;

impl Plugin for QuillshadeLoaderPlugin {
    fn build(&self, app: &mut App) {
        app.add_message::<QuillshadeProgress>()
            .add_message::<QuillshadeReady>()
            .init_resource::<QuillshadeLoaderState>()
            .add_systems(PreUpdate, track_quillshade_progress.after(material::LoadSet).after(light::LoadSet).after(data::LoadSet));
    }
}

/// Adds every enabled domain's plugin.
pub struct QuillshadePlugin;

impl Plugin for QuillshadePlugin {
    fn build(&self, app: &mut App) {
        app.add_plugins(material::QuillshadeMaterialInternalPlugin);
        app.add_plugins(light::QuillshadeLightInternalPlugin);
        app.add_plugins(data::DataDomainPlugin);
        app.add_plugins(QuillshadeLoaderPlugin);
    }
}
